import{_ as t,d as o,e as i,x as r}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"A.2 HV02 Boundaries and Interfaces (Full Interface Card)","description":"","frontmatter":{"title":"A.2 HV02 Boundaries and Interfaces (Full Interface Card)","xkChars":0,"xkWords":1019},"headers":[],"relativePath":"en/theory/appendix-a/a-02.md","filePath":"en/theory/appendix-a/a-02.md"}'),a={name:"en/theory/appendix-a/a-02.md"};function d(s,e,n,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<div class="theory-source"><h1 id="section-a-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.2</span><span class="xk-num__gap"></span></span>HV02 Boundaries and Interfaces (Full Interface Card) <a class="header-anchor" href="#section-a-2" aria-label="Permalink to &quot;A.2 HV02 Boundaries and Interfaces (Full Interface Card) {#section-a-2}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV02</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV02</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Boundaries and Interfaces</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>For human boundaries, record members, resources, information, rights, responsibilities, and cross-boundary interfaces together.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Human structures with inclusion, exclusion, exchange, or jurisdiction</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>Formal and actual boundaries are conflated or exclusions are invisible</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>1. <code>human_variable:HV01</code></td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. E1<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>None (empty set)</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV02-R0-boundary-inventory;<br>claim_level=descriptive_classification;<br>when=Members, resources, information, rights, responsibilities, cross-boundary interfaces, and differences between formal and actual boundaries can be recorded item by item;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Describe boundary states, interface accessibility, gatekeeping positions, records of refusal, and exclusion risks;<br>result_ceiling=An inventory of boundaries and interfaces only. Do not assert that the boundary has produced a causal selective effect.<br>2. route_id=HV02-R1-selective-effect;<br>claim_level=conditional_effect;<br>when=An eligible G2-instance shows that a pre-registered change to a boundary or interface has a channel effect above the threshold on the specified outcomes for cross-boundary flow, admission, or refusal;<br>additional_inferential_requires=G2-instance;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register the boundary’s selective effect and the distribution of cross-boundary costs for the specified channel, window, and position;<br>result_ceiling=Limited to tested channels and outcomes. Do not infer J-axis jurisdiction or authority to act from spatial extent, organizational scope, or scope of influence.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. Boundary selectivity. 2. Interface accessibility. 3. Cross-boundary costs</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Equating a boundary with closure<br>2. Equating membership status with consent<br>3. Equating scope of influence with jurisdiction</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers individual cross-boundary events, cases of interface use, populations by membership category, distributions of admission and refusal, and aggregation rules. X=Spatial extent covers physical points of entry, organizational boundaries, digital interfaces, legal jurisdictions, and cross-domain channels. T=Time span covers the period when a boundary is in force, waiting at interfaces, migration lags, and cycles of reorganization. O=Organizational level covers user roles, gatekeeping teams, organizations, institutions, and governance ecologies. C=Causal level covers cross-boundary events, mechanisms of gatekeeping interaction, interface structure, institutional rules, and systemic conditions. R=Resolution covers original admission and refusal records, sequences of use, individual cases, flow distributions, service metrics, and summaries. Record compression loss as well. I=Scope of influence covers direct users, people excluded, positions where benefits or costs occur indirectly, second-order spillovers, and impacts across domains and generations. N=Network topology scope covers interface nodes, gatekeeping bottlenecks, alternative paths, and cross-domain connections. J=Scope of jurisdiction and authorization requires separate authorization records for inclusion, exclusion, interface changes, and adjustments of rights and responsibilities. Scale elevation requires differences to be recorded axis by axis</td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>A boundary that selectively affects flows of resources, information, rights, or responsibilities</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. Positions inside and outside. 2. Cross-boundary channels. 3. Limits of rights and responsibilities</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. New membership categories<br>2. Interfaces across domains<br>3. Representation and authorization<br>4. Carryover of protections</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. Membership, interfaces, and the boundaries of actual control can change</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Nonhuman boundaries without concepts of membership, rights, or responsibility</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Treating greater spatial or organizational scope as automatically conferring jurisdiction</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Open<br>2. Selectively open<br>3. Closed<br>4. Disputed<br>5. Reorganizing</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Membership eligibility and decisions on admission and exit<br>2. Cross-boundary flows of resources, information, rights, and responsibilities<br>3. Gatekeeping nodes, wait times, and reasons for refusal<br>4. Differences between formal boundaries and boundaries of actual passage</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. Membership lists and exceptions<br>2. Records of interface use<br>3. Records of cross-boundary flows and refusals</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. The HV01 candidate object or supported structural domain and its evidential status<br>2. Roles and authorization. R0 does not require G1 to pass first</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. HV05 uptake<br>2. HV07 write-back<br>3. PF-9 exit</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Record lags in boundaries taking effect or changing and in exit and appeal</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record informal boundaries, access through representatives, and drift in digital spaces</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>Positions without access to the interface, without an exit, or withheld from disclosure for protection</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. Members<br>2. Applicants<br>3. People excluded<br>4. People bearing burdens outside the boundary</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Membership rules<br>2. Access mechanisms<br>3. Legal or institutional boundaries<br>4. Technical interfaces</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. Boundary setters. 2. Interface operators. 3. Parties granting authorization</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>Facts about a boundary are separate from its normative justification</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>Up to the diagnostic level when evidence about interfaces and impacts is sufficient</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only descriptions of boundary states, interface barriers, exclusion risks, and testing needs. It does not authorize changes to admission, exit, rights, or resource flows. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. The formal membership boundary is the opposite of the boundary of actual resource control<br>2. A digital interface is open, but physical, language, or safety barriers prevent some positions from gaining access</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, affected people inside and outside the boundary can challenge inclusion, exclusion, and interface barriers through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original decision chain for the boundary</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline correct membership and refusal records, actually restore affected admission rights or interface states, and reverse erroneous boundary actions. Preserve versions and verification of completion</td></tr></tbody></table></div></div>',1)])])}const f=t(a,[["render",d]]);export{b as __pageData,f as default};
